SELECT id, country
FROM suppliers
WHERE supplier_name <> 'EuroGoods GmbH' OR country IN ('SG', 'US') AND rating >= 2.7;

SELECT city FROM suppliers WHERE supplier_name = 'Lion City Imports'
MINUS
SELECT city FROM stores WHERE (city = 'Bangkok' OR store_name IS NOT NULL);

SELECT session_id FROM web_events WHERE page = '/home'
UNION
SELECT id FROM sessions WHERE device = 'mobile';

SELECT id FROM orders WHERE status <> 'SHIPPED'
EXCEPT
SELECT order_id FROM shipments WHERE cost < 76;

SELECT order_id, status FROM payments WHERE (amount >= 815 OR method <> 'promptpay') AND paid_at >= '2025-05-09 12:30:00'
EXCEPT
SELECT order_id, status FROM shipments WHERE (cost IS NOT NULL OR shipped_date >= '2023-07-23');

SELECT account_id FROM transactions WHERE (merchant = 'Amazon' OR is_flagged = TRUE)
UNION
SELECT id FROM accounts WHERE account_type IN ('CHECKING', 'LOAN');

select opened_date, customer_id from accounts where (balance < 19258 or account_type in ('LOAN', 'SAVINGS')) and (account_type in ('CREDIT', 'SAVINGS') or status in ('CLOSED', 'FROZEN'))
except all
select opened_date, customer_id from accounts where (status = 'FROZEN' or opened_date > '2025-02-25');
